"use strict";
const pptxgen = require("pptxgenjs");
const path = require("path");

const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.title = "DeepSeek-V2: Efficient MoE Language Model with Multi-Head Latent Attention";
pres.author = "ML Research";

// ── Palette ──────────────────────────────────────────────────────────────────
const C = {
  darkBg:    "0D1117",   // near-black (title/section backgrounds)
  midBg:     "161B22",   // slightly lighter dark
  cardBg:    "1C2330",   // card background
  lightBg:   "F6F8FA",   // light slide background
  accent:    "58A6FF",   // electric blue accent
  accent2:   "3FB950",   // green accent
  accent3:   "F78166",   // orange-red accent
  white:     "FFFFFF",
  offWhite:  "E6EDF3",
  muted:     "8B949E",
  darkText:  "1C2330",
};

// ── Shared helpers ─────────────────────────────────────────────────────────
function makeShadow() {
  return { type: "outer", blur: 8, offset: 2, angle: 135, color: "000000", opacity: 0.2 };
}

function addSlideHeader(slide, title, light = false) {
  // Top accent bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.06,
    fill: { color: C.accent }, line: { color: C.accent }
  });
  slide.addText(title, {
    x: 0.5, y: 0.15, w: 9, h: 0.65,
    fontSize: 22, bold: true, fontFace: "Calibri",
    color: light ? C.darkText : C.white,
    align: "left", valign: "middle", margin: 0
  });
}

function addFooter(slide, light = false) {
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 5.4, w: 10, h: 0.225,
    fill: { color: light ? "E2EBF5" : C.midBg }, line: { color: light ? "E2EBF5" : C.midBg }
  });
  slide.addText("DeepSeek-V2  ·  arxiv.org/abs/2405.04434", {
    x: 0.4, y: 5.4, w: 9.2, h: 0.225,
    fontSize: 9, color: C.muted, align: "left", valign: "middle", margin: 0
  });
}

// ══════════════════════════════════════════════════════════════════════════════
// SLIDE 1 – Title
// ══════════════════════════════════════════════════════════════════════════════
{
  const s = pres.addSlide();
  s.background = { color: C.darkBg };

  // Left accent bar
  s.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 0.35, h: 5.625,
    fill: { color: C.accent }, line: { color: C.accent }
  });

  // Top label
  s.addText("RESEARCH PAPER OVERVIEW", {
    x: 0.6, y: 0.55, w: 8, h: 0.35,
    fontSize: 10, bold: true, fontFace: "Calibri", charSpacing: 5,
    color: C.accent, align: "left", valign: "middle", margin: 0
  });

  // Main title
  s.addText("DeepSeek-V2", {
    x: 0.6, y: 1.05, w: 8.8, h: 0.85,
    fontSize: 48, bold: true, fontFace: "Calibri",
    color: C.white, align: "left", margin: 0
  });
  s.addText("Efficient MoE Language Model\nwith Multi-Head Latent Attention", {
    x: 0.6, y: 1.88, w: 8, h: 0.95,
    fontSize: 22, fontFace: "Calibri",
    color: C.offWhite, align: "left", margin: 0
  });

  // Stats row
  const stats = [
    { val: "236B", lbl: "Total Parameters" },
    { val: "21B",  lbl: "Activated per Token" },
    { val: "128K", lbl: "Context Length" },
  ];
  const sx = [0.6, 3.5, 6.4];
  stats.forEach((st, i) => {
    s.addShape(pres.shapes.RECTANGLE, {
      x: sx[i], y: 3.08, w: 2.6, h: 1.08,
      fill: { color: C.cardBg }, line: { color: C.accent, pt: 1 },
      shadow: makeShadow()
    });
    s.addText(st.val, {
      x: sx[i] + 0.12, y: 3.12, w: 2.36, h: 0.55,
      fontSize: 30, bold: true, fontFace: "Calibri",
      color: C.accent, align: "center", valign: "bottom", margin: 0
    });
    s.addText(st.lbl, {
      x: sx[i] + 0.12, y: 3.65, w: 2.36, h: 0.4,
      fontSize: 11, fontFace: "Calibri",
      color: C.muted, align: "center", valign: "top", margin: 0
    });
  });

  // Tagline
  s.addText("A Strong, Economical, and Efficient Language Model", {
    x: 0.6, y: 4.4, w: 8.5, h: 0.4,
    fontSize: 13, italic: true, fontFace: "Calibri",
    color: C.muted, align: "left", margin: 0
  });

  addFooter(s);
}

// ══════════════════════════════════════════════════════════════════════════════
// SLIDE 2 – Motivation and Challenge
// ══════════════════════════════════════════════════════════════════════════════
{
  const s = pres.addSlide();
  s.background = { color: C.lightBg };
  addSlideHeader(s, "The LLM Scaling Dilemma: Performance vs. Cost and Speed", true);
  addFooter(s, true);

  // Three challenge cards
  const cards = [
    {
      icon: "▲",
      title: "Larger Models = Better Performance",
      body: "Dense scaling laws demand proportionally more parameters to push capability — driving models to 70B, 100B+ parameters.",
      col: C.accent
    },
    {
      icon: "⚠",
      title: "KV Cache Bottleneck",
      body: "Multi-Head Attention stores O(n·h·d) keys and values per layer. At 128K context, this becomes a critical memory constraint limiting throughput.",
      col: C.accent3
    },
    {
      icon: "$",
      title: "Prohibitive Training Costs",
      body: "Dense 67B models are expensive to train. Scaling further without efficiency gains is economically infeasible for most teams.",
      col: C.accent2
    }
  ];

  cards.forEach((c, i) => {
    const cx = 0.35 + i * 3.13;
    s.addShape(pres.shapes.RECTANGLE, {
      x: cx, y: 1.05, w: 2.95, h: 3.95,
      fill: { color: C.white }, line: { color: "DDE5EF", pt: 1 },
      shadow: makeShadow()
    });
    // Top colored accent
    s.addShape(pres.shapes.RECTANGLE, {
      x: cx, y: 1.05, w: 2.95, h: 0.07,
      fill: { color: c.col }, line: { color: c.col }
    });
    // Icon circle
    s.addShape(pres.shapes.OVAL, {
      x: cx + 1.1, y: 1.25, w: 0.75, h: 0.75,
      fill: { color: c.col, transparency: 85 }, line: { color: c.col, pt: 1 }
    });
    s.addText(c.icon, {
      x: cx + 1.1, y: 1.25, w: 0.75, h: 0.75,
      fontSize: 18, bold: true, fontFace: "Calibri",
      color: c.col, align: "center", valign: "middle", margin: 0
    });
    s.addText(c.title, {
      x: cx + 0.15, y: 2.15, w: 2.65, h: 0.65,
      fontSize: 13, bold: true, fontFace: "Calibri",
      color: C.darkText, align: "center", margin: 0
    });
    s.addText(c.body, {
      x: cx + 0.15, y: 2.85, w: 2.65, h: 1.85,
      fontSize: 11.5, fontFace: "Calibri",
      color: "445566", align: "left", valign: "top", margin: 0
    });
  });

  // Solution teaser
  s.addShape(pres.shapes.RECTANGLE, {
    x: 0.35, y: 5.08, w: 9.3, h: 0.25,
    fill: { color: C.accent, transparency: 90 }, line: { color: C.accent, pt: 1 }
  });
  s.addText("Solution: DeepSeek-V2 addresses all three with MLA + DeepSeekMoE — cutting cost 42.5%, cache 93.3%, boosting throughput 5.76×", {
    x: 0.5, y: 5.05, w: 9.1, h: 0.3,
    fontSize: 10.5, fontFace: "Calibri", italic: true,
    color: C.accent, align: "center", valign: "middle", margin: 0
  });
}

// ══════════════════════════════════════════════════════════════════════════════
// SLIDE 3 – Architecture Overview
// ══════════════════════════════════════════════════════════════════════════════
{
  const s = pres.addSlide();
  s.background = { color: C.darkBg };
  addSlideHeader(s, "DeepSeek-V2 Architecture: MLA + DeepSeekMoE in Each Transformer Block");
  addFooter(s);

  // Architecture figure (left)
  s.addImage({
    path: "/app/benchmark/assets/figure_1.jpg",
    x: 0.35, y: 0.95, w: 4.6, h: 4.2,
    sizing: { type: "contain", w: 4.6, h: 4.2 }
  });

  // Right: annotation cards
  const items = [
    { hdr: "MLA — Attention Layer", body: "Replaces standard MHA. Low-rank key-value compression caches a compact latent vector instead of full K/V pairs.", col: C.accent },
    { hdr: "DeepSeekMoE — FFN Layer", body: "Replaces dense FFN with fine-grained shared + routed experts. Only a subset of experts activates per token.", col: C.accent2 },
    { hdr: "Scale", body: "236B total params · 21B activated · 128K context · 61 Transformer layers", col: C.accent3 },
  ];

  items.forEach((it, i) => {
    const ry = 1.0 + i * 1.42;
    s.addShape(pres.shapes.RECTANGLE, {
      x: 5.25, y: ry, w: 4.4, h: 1.25,
      fill: { color: C.cardBg }, line: { color: it.col, pt: 1 },
      shadow: makeShadow()
    });
    s.addShape(pres.shapes.RECTANGLE, {
      x: 5.25, y: ry, w: 0.07, h: 1.25,
      fill: { color: it.col }, line: { color: it.col }
    });
    s.addText(it.hdr, {
      x: 5.45, y: ry + 0.08, w: 4.1, h: 0.35,
      fontSize: 13, bold: true, fontFace: "Calibri",
      color: C.white, align: "left", valign: "top", margin: 0
    });
    s.addText(it.body, {
      x: 5.45, y: ry + 0.45, w: 4.1, h: 0.72,
      fontSize: 11, fontFace: "Calibri",
      color: C.offWhite, align: "left", valign: "top", margin: 0
    });
  });
}

// ══════════════════════════════════════════════════════════════════════════════
// SLIDE 4 – MLA Mechanism
// ══════════════════════════════════════════════════════════════════════════════
{
  const s = pres.addSlide();
  s.background = { color: C.lightBg };
  addSlideHeader(s, "Multi-Head Latent Attention: 93.3% KV Cache Compression", true);
  addFooter(s, true);

  // Left: figure_2
  s.addImage({
    path: "/app/benchmark/assets/figure_2.jpg",
    x: 0.35, y: 1.0, w: 4.7, h: 4.0,
    sizing: { type: "contain", w: 4.7, h: 4.0 }
  });

  // Right: explanation cards
  const rows = [
    { lbl: "Standard MHA", desc: "Caches full K and V vectors per head per token → memory bottleneck at long contexts.", bad: true },
    { lbl: "GQA / MQA", desc: "Reduce cache by sharing heads, but sacrifice model quality to do so.", bad: true },
    { lbl: "MLA (DeepSeek-V2)", desc: "Low-rank joint compression: caches a single latent vector c_KV per token. Full K/V reconstructed via learned projections. Decoupled RoPE for positional encoding.", bad: false },
  ];

  rows.forEach((r, i) => {
    const ry = 1.08 + i * 1.3;
    const col = r.bad ? C.accent3 : C.accent2;
    s.addShape(pres.shapes.RECTANGLE, {
      x: 5.3, y: ry, w: 4.35, h: 1.18,
      fill: { color: C.white }, line: { color: col, pt: 1 },
      shadow: makeShadow()
    });
    s.addShape(pres.shapes.RECTANGLE, {
      x: 5.3, y: ry, w: 0.07, h: 1.18,
      fill: { color: col }, line: { color: col }
    });
    s.addText(r.lbl, {
      x: 5.5, y: ry + 0.06, w: 4.0, h: 0.32,
      fontSize: 13, bold: true, fontFace: "Calibri",
      color: C.darkText, align: "left", valign: "top", margin: 0
    });
    s.addText(r.desc, {
      x: 5.5, y: ry + 0.4, w: 4.0, h: 0.7,
      fontSize: 11, fontFace: "Calibri",
      color: "445566", align: "left", valign: "top", margin: 0
    });
  });

  // Key result badge
  s.addShape(pres.shapes.RECTANGLE, {
    x: 5.3, y: 4.98, w: 4.35, h: 0.3,
    fill: { color: C.accent, transparency: 88 }, line: { color: C.accent, pt: 1 }
  });
  s.addText("Result: MLA outperforms MHA while using 93.3% less KV cache", {
    x: 5.35, y: 4.98, w: 4.25, h: 0.3,
    fontSize: 10.5, bold: true, fontFace: "Calibri", italic: true,
    color: C.accent, align: "center", valign: "middle", margin: 0
  });
}

// ══════════════════════════════════════════════════════════════════════════════
// SLIDE 5 – DeepSeekMoE
// ══════════════════════════════════════════════════════════════════════════════
{
  const s = pres.addSlide();
  s.background = { color: C.darkBg };
  addSlideHeader(s, "DeepSeekMoE: Fine-Grained Experts with Shared Expert Isolation");
  addFooter(s);

  // Two-column layout
  // Left: 2×2 feature cards
  const features = [
    { title: "Shared Experts (N_s)", body: "Always activated — capture universal knowledge common across all tokens and tasks.", col: C.accent },
    { title: "Routed Experts (N_r)", body: "Sparsely activated via top-K_r router. Fine-grained segmentation boosts specialization.", col: C.accent2 },
    { title: "Device-Limited Routing", body: "Constrains each token to experts on at most M devices, reducing costly cross-node communication.", col: C.accent3 },
    { title: "Load Balancing", body: "Auxiliary losses enforce balanced utilization. Token-dropping strategy prevents expert overflow during training.", col: "C09553" },
  ];

  const positions = [
    { x: 0.35, y: 1.0 },
    { x: 0.35, y: 2.6 },
    { x: 5.2,  y: 1.0 },
    { x: 5.2,  y: 2.6 },
  ];

  features.forEach((f, i) => {
    const pos = positions[i];
    s.addShape(pres.shapes.RECTANGLE, {
      x: pos.x, y: pos.y, w: 4.6, h: 1.42,
      fill: { color: C.cardBg }, line: { color: f.col, pt: 1 },
      shadow: makeShadow()
    });
    s.addShape(pres.shapes.RECTANGLE, {
      x: pos.x, y: pos.y, w: 0.07, h: 1.42,
      fill: { color: f.col }, line: { color: f.col }
    });
    s.addText(f.title, {
      x: pos.x + 0.2, y: pos.y + 0.1, w: 4.2, h: 0.38,
      fontSize: 13, bold: true, fontFace: "Calibri",
      color: C.white, align: "left", valign: "top", margin: 0
    });
    s.addText(f.body, {
      x: pos.x + 0.2, y: pos.y + 0.52, w: 4.2, h: 0.78,
      fontSize: 11, fontFace: "Calibri",
      color: C.offWhite, align: "left", valign: "top", margin: 0
    });
  });

