"use strict";
const pptxgen = require("pptxgenjs");

const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.title = "DeepSeek-V2: Efficient MoE Language Model with Multi-Head Latent Attention";

// ── Palette ──────────────────────────────────────────────────────────────────
const C = {
  darkBg:   "0D1117",
  midBg:    "161B22",
  cardBg:   "1C2330",
  lightBg:  "F6F8FA",
  accent:   "58A6FF",  // blue
  accent2:  "3FB950",  // green
  accent3:  "F78166",  // orange-red
  accent4:  "E3B341",  // gold/yellow
  accent5:  "BC8CFF",  // purple
  white:    "FFFFFF",
  offWhite: "E6EDF3",
  muted:    "8B949E",
  darkText: "1C2330",
  bodyText: "374151",
};

function makeShadow() {
  return { type: "outer", blur: 8, offset: 2, angle: 135, color: "000000", opacity: 0.18 };
}

function addTopBar(slide, color) {
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.07,
    fill: { color }, line: { color }
  });
}

function addSlideTitle(slide, text, light) {
  slide.addText(text, {
    x: 0.5, y: 0.12, w: 9, h: 0.72,
    fontSize: 21, bold: true, fontFace: "Calibri",
    color: light ? C.darkText : C.offWhite,
