  });
}

// Card helper: draws rectangle with left accent strip
function addCard(slide, x, y, w, h, accentColor, bgColor, borderColor) {
  const bg = bgColor || C.cardBg;
  const border = borderColor || accentColor;
  slide.addShape(pres.shapes.RECTANGLE, {
    x, y, w, h,
    fill: { color: bg }, line: { color: border, pt: 1 },
    shadow: makeShadow()
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x, y, w: 0.07, h,
    fill: { color: accentColor }, line: { color: accentColor }
  });
}

