"use strict";
const pptxgen = require("pptxgenjs");

const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.title = "DeepSeek-V2: Efficient MoE Language Model with Multi-Head Latent Attention";

// ── Palette ──────────────────────────────────────────────────────────────────
const C = {
  darkBg:   "0D1117",
  midBg:    "161B22",
  cardBg:   "1C2330",
  lightBg:  "F6F8FA",
  accent:   "58A6FF",  // blue
  accent2:  "3FB950",  // green
  accent3:  "F78166",  // orange-red
  accent4:  "E3B341",  // gold/yellow
  accent5:  "BC8CFF",  // purple
  white:    "FFFFFF",
  offWhite: "E6EDF3",
  muted:    "8B949E",
  darkText: "1C2330",
  bodyText: "374151",
};

function makeShadow() {
  return { type: "outer", blur: 8, offset: 2, angle: 135, color: "000000", opacity: 0.18 };
}

function addTopBar(slide, color) {
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.07,
    fill: { color }, line: { color }
  });
}

function addSlideTitle(slide, text, light) {
  slide.addText(text, {
    x: 0.5, y: 0.12, w: 9, h: 0.72,
    fontSize: 21, bold: true, fontFace: "Calibri",
    color: light ? C.darkText : C.offWhite,
    align: "left", valign: "middle", margin: 0
  });
}

function addFooter(slide, light) {
  const bg = light ? "DDE5F0" : "1A2232";
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 5.4, w: 10, h: 0.225,
    fill: { color: bg }, line: { color: bg }
  });
  slide.addText("DeepSeek-V2  ·  arxiv.org/abs/2405.04434", {
    x: 0.4, y: 5.4, w: 9.2, h: 0.225,
    fontSize: 9, color: C.muted, fontFace: "Calibri",
    align: "left", valign: "middle", margin: 0
  });
}

// Card helper: draws rectangle with left accent strip
function addCard(slide, x, y, w, h, accentColor, bgColor, borderColor) {
  const bg = bgColor || C.cardBg;
  const border = borderColor || accentColor;
  slide.addShape(pres.shapes.RECTANGLE, {
    x, y, w, h,
    fill: { color: bg }, line: { color: border, pt: 1 },
    shadow: makeShadow()
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x, y, w: 0.07, h,
    fill: { color: accentColor }, line: { color: accentColor }
  });
}

// ══════════════════════════════════════════════════════════════════════════════
// SLIDE 1 – Title
// ══════════════════════════════════════════════════════════════════════════════
{
  const s = pres.addSlide();
  s.background = { color: C.darkBg };

  // Left vertical accent bar
  s.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 0.35, h: 5.625,
    fill: { color: C.accent }, line: { color: C.accent }
  });

  s.addText("RESEARCH PAPER OVERVIEW", {
    x: 0.6, y: 0.52, w: 8.5, h: 0.32,
    fontSize: 10, bold: true, fontFace: "Calibri", charSpacing: 5,
    color: C.accent, align: "left", valign: "middle", margin: 0
  });

  s.addText("DeepSeek-V2", {
    x: 0.6, y: 0.88, w: 9, h: 0.9,
    fontSize: 50, bold: true, fontFace: "Calibri",
    color: C.white, align: "left", margin: 0
  });
  s.addText("Efficient MoE Language Model\nwith Multi-Head Latent Attention", {
    x: 0.6, y: 1.8, w: 8.5, h: 0.9,
    fontSize: 22, fontFace: "Calibri",
    color: C.offWhite, align: "left", margin: 0
  });

  // Divider line
  s.addShape(pres.shapes.LINE, {
    x: 0.6, y: 2.85, w: 8.8, h: 0,
    line: { color: "2A3A5A", width: 1 }
  });

  // Stats
  const stats = [
    { val: "236B", lbl: "Total Parameters" },
    { val: "21B",  lbl: "Activated per Token" },
    { val: "128K", lbl: "Context Window" },
  ];
  const sx = [0.6, 3.63, 6.66];
  stats.forEach((st, i) => {
    s.addShape(pres.shapes.RECTANGLE, {
      x: sx[i], y: 3.0, w: 2.8, h: 1.3,
      fill: { color: C.cardBg }, line: { color: C.accent, pt: 1 },
      shadow: makeShadow()
    });
    s.addText(st.val, {
      x: sx[i] + 0.1, y: 3.08, w: 2.6, h: 0.68,
      fontSize: 34, bold: true, fontFace: "Calibri",
      color: C.accent, align: "center", valign: "bottom", margin: 0
    });
    s.addText(st.lbl, {
      x: sx[i] + 0.1, y: 3.76, w: 2.6, h: 0.42,
      fontSize: 11.5, fontFace: "Calibri",
      color: C.offWhite, align: "center", valign: "top", margin: 0
    });
  });

  s.addText("A Strong, Economical, and Efficient Language Model  ·  DeepSeek AI (2024)", {
    x: 0.6, y: 4.5, w: 8.8, h: 0.32,
    fontSize: 11, italic: true, fontFace: "Calibri",
    color: C.offWhite, align: "left", margin: 0
  });

  addFooter(s);
}

// ══════════════════════════════════════════════════════════════════════════════
// SLIDE 2 – Motivation and Challenge
// ══════════════════════════════════════════════════════════════════════════════
{
  const s = pres.addSlide();
  s.background = { color: C.lightBg };
  addTopBar(s, C.accent);
  addSlideTitle(s, "The LLM Scaling Dilemma: Performance vs. Training Cost and Inference Speed", true);
  addFooter(s, true);

  const cards = [
    {
      icon: "▲",
      title: "Larger Models = Better Intelligence",
      body: "Dense scaling laws demand proportionally more parameters. State-of-the-art models exceed 70B parameters — every gain in quality multiplies training and inference cost.",
      col: C.accent
    },
    {
      icon: "⚠",
      title: "KV Cache Bottleneck",
      body: "Multi-Head Attention caches O(n·h·d) key/value vectors per layer. At 128K context windows this becomes the dominant memory constraint, throttling generation throughput.",
      col: C.accent3
    },
    {
      icon: "$",
      title: "Prohibitive Training Cost",
      body: "Training a dense 67B model is already expensive. Scaling without architectural efficiency gains is economically infeasible — and wasteful if most parameters aren't needed.",
      col: C.accent2
    }
  ];

  const cardH = 3.52;
  cards.forEach((c, i) => {
    const cx = 0.35 + i * 3.13;
    s.addShape(pres.shapes.RECTANGLE, {
      x: cx, y: 1.02, w: 2.95, h: cardH,
      fill: { color: C.white }, line: { color: "D8E0EC", pt: 1 },
      shadow: makeShadow()
    });
    s.addShape(pres.shapes.RECTANGLE, {
      x: cx, y: 1.02, w: 2.95, h: 0.07,
      fill: { color: c.col }, line: { color: c.col }
    });
    // Icon circle
    s.addShape(pres.shapes.OVAL, {
      x: cx + 1.1, y: 1.22, w: 0.75, h: 0.75,
      fill: { color: c.col, transparency: 82 }, line: { color: c.col, pt: 1 }
    });
    s.addText(c.icon, {
      x: cx + 1.1, y: 1.22, w: 0.75, h: 0.75,
      fontSize: 20, bold: true, fontFace: "Calibri",
      color: c.col, align: "center", valign: "middle", margin: 0
    });
    s.addText(c.title, {
      x: cx + 0.14, y: 2.1, w: 2.67, h: 0.6,
      fontSize: 13, bold: true, fontFace: "Calibri",
      color: C.darkText, align: "center", margin: 0
    });
    s.addText(c.body, {
      x: cx + 0.14, y: 2.73, w: 2.67, h: 1.68,
      fontSize: 11.5, fontFace: "Calibri",
      color: C.bodyText, align: "left", valign: "top", margin: 0
    });
  });

  // Solution banner — dark background for contrast
  s.addShape(pres.shapes.RECTANGLE, {
    x: 0.35, y: 4.72, w: 9.3, h: 0.4,
    fill: { color: "1A2A42" }, line: { color: C.accent, pt: 1 }
  });
  s.addText("Solution: DeepSeek-V2 addresses all three — 42.5% lower training cost, 93.3% KV cache reduction, 5.76× generation throughput", {
    x: 0.55, y: 4.72, w: 9.0, h: 0.4,
    fontSize: 11, bold: true, fontFace: "Calibri",
    color: C.offWhite, align: "center", valign: "middle", margin: 0
  });
}

// ══════════════════════════════════════════════════════════════════════════════
// SLIDE 3 – Architecture Overview
// ══════════════════════════════════════════════════════════════════════════════
{
  const s = pres.addSlide();
  s.background = { color: C.darkBg };
  addTopBar(s, C.accent);
  addSlideTitle(s, "DeepSeek-V2 Architecture: MLA + DeepSeekMoE in Each Transformer Block");
  addFooter(s);

  // Figure with margin
  s.addImage({
    path: "/app/benchmark/assets/figure_1.jpg",
    x: 0.5, y: 0.95, w: 4.5, h: 4.15,
    sizing: { type: "contain", w: 4.5, h: 4.15 }
  });

  // 3 annotation cards — evenly spaced
  const items = [
    { hdr: "MLA — Attention Layer", body: "Replaces standard MHA with low-rank key-value joint compression. A compact latent vector is cached per token; full K/V reconstructed on-the-fly.", col: C.accent },
    { hdr: "DeepSeekMoE — FFN Layer", body: "Replaces the dense FFN with fine-grained shared + sparsely routed experts. Only 21B of 236B parameters activate per token.", col: C.accent2 },
    { hdr: "Scale & Training", body: "236B total params · 21B activated · 128K context · Pretrained on 8.1T tokens from a multi-source corpus.", col: C.accent4 },
  ];

  const cardH = 1.3;
  const gapY = 0.12;
  const startY = 0.95;
  items.forEach((it, i) => {
    const ry = startY + i * (cardH + gapY);
    addCard(s, 5.3, ry, 4.35, cardH, it.col);
    s.addText(it.hdr, {
      x: 5.52, y: ry + 0.1, w: 3.98, h: 0.38,
      fontSize: 13, bold: true, fontFace: "Calibri",
      color: C.white, align: "left", valign: "top", margin: 0
    });
    s.addText(it.body, {
      x: 5.52, y: ry + 0.5, w: 3.98, h: 0.72,
      fontSize: 11, fontFace: "Calibri",
      color: C.offWhite, align: "left", valign: "top", margin: 0
    });
  });
}

// ══════════════════════════════════════════════════════════════════════════════
// SLIDE 4 – MLA Mechanism
// ══════════════════════════════════════════════════════════════════════════════
{
  const s = pres.addSlide();
  s.background = { color: C.lightBg };
  addTopBar(s, C.accent);
  addSlideTitle(s, "Multi-Head Latent Attention: 93.3% KV Cache Compression", true);
  addFooter(s, true);

  s.addImage({
    path: "/app/benchmark/assets/figure_2.jpg",
    x: 0.4, y: 0.95, w: 4.7, h: 4.1,
    sizing: { type: "contain", w: 4.7, h: 4.1 }
  });

  // 3 comparison cards — equal height, fill right column
  const rows = [
    { lbl: "Standard MHA", desc: "Caches full K and V vectors for every attention head per token. At long contexts this becomes a severe memory bottleneck that limits batch size and throughput.", col: C.accent3 },
    { lbl: "GQA / MQA",    desc: "Reduce cache by sharing or merging heads across groups. Lowers memory but sacrifices performance compared to full MHA — a quality–efficiency tradeoff.", col: C.accent4 },
    { lbl: "MLA (DeepSeek-V2)", desc: "Low-rank joint KV compression: caches a single compact latent vector c_KV per token. Full K/V reconstructed via learned projections. Decoupled RoPE for positional encoding. Achieves better performance than MHA with 93.3% less cache.", col: C.accent2 },
  ];

  const totalH = 4.1;
  const cardH = (totalH - 2 * 0.1) / 3;
  rows.forEach((r, i) => {
    const ry = 0.95 + i * (cardH + 0.1);
    addCard(s, 5.35, ry, 4.3, cardH, r.col, C.white, r.col);
    s.addText(r.lbl, {
      x: 5.57, y: ry + 0.09, w: 3.95, h: 0.34,
      fontSize: 13, bold: true, fontFace: "Calibri",
      color: C.darkText, align: "left", valign: "top", margin: 0
    });
    s.addText(r.desc, {
      x: 5.57, y: ry + 0.46, w: 3.95, h: cardH - 0.55,
      fontSize: 11, fontFace: "Calibri",
      color: C.bodyText, align: "left", valign: "top", margin: 0
    });
  });

  // Result badge — dark bg for contrast
  s.addShape(pres.shapes.RECTANGLE, {
    x: 5.35, y: 0.95 + totalH + 0.08, w: 4.3, h: 0.35,
    fill: { color: "1A3040" }, line: { color: C.accent2, pt: 1 }
  });
  s.addText("Result: MLA outperforms MHA while using 93.3% less KV cache", {
    x: 5.4, y: 0.95 + totalH + 0.08, w: 4.2, h: 0.35,
    fontSize: 10.5, bold: true, fontFace: "Calibri",
    color: C.accent2, align: "center", valign: "middle", margin: 0
  });
}

// ══════════════════════════════════════════════════════════════════════════════
// SLIDE 5 – DeepSeekMoE
// ══════════════════════════════════════════════════════════════════════════════
{
  const s = pres.addSlide();
  s.background = { color: C.darkBg };
  addTopBar(s, C.accent2);
  addSlideTitle(s, "DeepSeekMoE: Fine-Grained Experts with Shared Expert Isolation");
  addFooter(s);

  // 2×2 grid with consistent spacing
  const cardW = 4.55;
  const cardH = 1.62;
  const gapX = 0.25;
  const gapY = 0.2;
  const startX = 0.35;
  const startY = 0.98;

  const features = [
    { title: "Shared Experts (N_s)", body: "Always activated — capture universal knowledge common across all tokens and tasks, preventing expert redundancy in routed layers.", col: C.accent },
    { title: "Routed Experts (N_r)", body: "Sparsely activated via top-K_r router. Fine-grained expert segmentation increases the potential for specialization per knowledge domain.", col: C.accent2 },
    { title: "Device-Limited Routing", body: "Each token is constrained to experts residing on at most M devices, drastically reducing expensive cross-node communication during training and inference.", col: C.accent3 },
    { title: "Load Balancing & Overflow", body: "Auxiliary losses enforce balanced utilization across experts and devices. A token-dropping strategy during training prevents expert overflow without affecting inference quality.", col: C.accent4 },
  ];

  const positions = [
    { c: 0, r: 0 },
    { c: 0, r: 1 },
    { c: 1, r: 0 },
    { c: 1, r: 1 },
  ];

  features.forEach((f, i) => {
    const px = startX + positions[i].c * (cardW + gapX);
    const py = startY + positions[i].r * (cardH + gapY);
    addCard(s, px, py, cardW, cardH, f.col);
    s.addText(f.title, {
      x: px + 0.22, y: py + 0.12, w: cardW - 0.32, h: 0.38,
      fontSize: 13, bold: true, fontFace: "Calibri",
      color: C.white, align: "left", valign: "top", margin: 0
    });
    s.addText(f.body, {
      x: px + 0.22, y: py + 0.54, w: cardW - 0.32, h: cardH - 0.6,
      fontSize: 11, fontFace: "Calibri",
      color: C.offWhite, align: "left", valign: "top", margin: 0
    });
  });

  // Result bar
  const barY = startY + 2 * (cardH + gapY) + 0.1;
  s.addShape(pres.shapes.RECTANGLE, {
    x: 0.35, y: barY, w: 9.3, h: 0.55,
    fill: { color: C.cardBg }, line: { color: C.accent2, pt: 1.5 },
    shadow: makeShadow()
  });
  s.addText([
    { text: "Result: ", options: { bold: true, color: C.accent2 } },
    { text: "236B total parameters, only 21B activated — training costs ", options: { color: C.offWhite } },
    { text: "42.5% lower", options: { bold: true, color: C.accent2 } },
    { text: " than a 67B dense predecessor model.", options: { color: C.offWhite } },
  ], {
    x: 0.55, y: barY, w: 9.0, h: 0.55,
    fontSize: 12, fontFace: "Calibri",
    align: "left", valign: "middle", margin: 0
  });
}

// ══════════════════════════════════════════════════════════════════════════════
// SLIDE 6 – Efficiency Gains
// ══════════════════════════════════════════════════════════════════════════════
{
  const s = pres.addSlide();
  s.background = { color: C.lightBg };
  addTopBar(s, C.accent);
  addSlideTitle(s, "42.5% Training Cost Reduction and 5.76× Generation Throughput vs. DeepSeek 67B", true);
  addFooter(s, true);

  const colW = 4.2;
  const col1x = 0.5;
  const col2x = 5.3;

  // Column headers
  s.addShape(pres.shapes.RECTANGLE, {
    x: col1x, y: 1.02, w: colW, h: 0.42,
    fill: { color: "3A4A5E" }, line: { color: "3A4A5E" }
  });
  s.addText("DeepSeek 67B  (Dense Baseline)", {
    x: col1x, y: 1.02, w: colW, h: 0.42,
    fontSize: 12.5, bold: true, fontFace: "Calibri",
    color: C.white, align: "center", valign: "middle", margin: 0
  });

  s.addShape(pres.shapes.RECTANGLE, {
    x: col2x, y: 1.02, w: colW, h: 0.42,
    fill: { color: C.accent }, line: { color: C.accent }
  });
  s.addText("DeepSeek-V2  (MoE)", {
    x: col2x, y: 1.02, w: colW, h: 0.42,
    fontSize: 12.5, bold: true, fontFace: "Calibri",
    color: C.white, align: "center", valign: "middle", margin: 0
  });

  const metrics = [
    { label: "Training Cost",             leftVal: "Baseline",   rightVal: "−42.5%",  col: C.accent2 },
    { label: "KV Cache Size",             leftVal: "Baseline",   rightVal: "−93.3%",  col: C.accent  },
    { label: "Max Generation Throughput", leftVal: "1×",         rightVal: "5.76×",   col: C.accent3 },
  ];

  const metricH = 1.18;
  const metricGap = 0.1;
  metrics.forEach((m, i) => {
    const ry = 1.55 + i * (metricH + metricGap);

    // Left card — dense baseline, dark header strip for label contrast
    s.addShape(pres.shapes.RECTANGLE, {
      x: col1x, y: ry, w: colW, h: metricH,
      fill: { color: C.white }, line: { color: "C4CDD8", pt: 1 }
    });
    s.addShape(pres.shapes.RECTANGLE, {
      x: col1x, y: ry, w: colW, h: 0.3,
      fill: { color: "E8EDF5" }, line: { color: "E8EDF5" }
    });
    s.addText(m.label, {
      x: col1x + 0.1, y: ry, w: colW - 0.2, h: 0.3,
      fontSize: 11, bold: true, fontFace: "Calibri",
      color: C.darkText, align: "left", valign: "middle", margin: 0
    });
    s.addText(m.leftVal, {
      x: col1x + 0.1, y: ry + 0.3, w: colW - 0.2, h: metricH - 0.3,
      fontSize: 28, bold: true, fontFace: "Calibri",
      color: "5A6A7E", align: "center", valign: "middle", margin: 0
    });

    // Right card — improvement
    addCard(s, col2x, ry, colW, metricH, m.col, C.white, m.col);
    s.addShape(pres.shapes.RECTANGLE, {
      x: col2x + 0.07, y: ry, w: colW - 0.07, h: 0.3,
      fill: { color: "E8EDF5" }, line: { color: "E8EDF5" }
    });
    s.addText(m.label, {
      x: col2x + 0.2, y: ry, w: colW - 0.3, h: 0.3,
      fontSize: 11, bold: true, fontFace: "Calibri",
      color: C.darkText, align: "left", valign: "middle", margin: 0
    });
    s.addText(m.rightVal, {
      x: col2x + 0.2, y: ry + 0.3, w: colW - 0.3, h: metricH - 0.3,
      fontSize: 30, bold: true, fontFace: "Calibri",
      color: m.col, align: "center", valign: "middle", margin: 0
    });
  });

  s.addText("All metrics are relative to DeepSeek 67B. No absolute FLOPs, cache sizes, or throughput numbers have been fabricated.", {
    x: 0.5, y: 5.1, w: 9, h: 0.22,
    fontSize: 9, italic: true, fontFace: "Calibri",
    color: C.muted, align: "center", margin: 0
  });
}

// ══════════════════════════════════════════════════════════════════════════════
// SLIDE 7 – MMLU Performance (manual dot plot + table)
// ══════════════════════════════════════════════════════════════════════════════
{
  const s = pres.addSlide();
  s.background = { color: C.darkBg };
  addTopBar(s, C.accent);
  addSlideTitle(s, "DeepSeek-V2 Tops MMLU at Only 21B Activated Parameters");
  addFooter(s);

  // ── Manual scatter / dot plot ──────────────────────────────────────────────
  // Plot area: x 0.5–5.6 (w=5.1"), y 1.05–4.85 (h=3.8")
  // X-axis: Activated params 0–80B
  // Y-axis: MMLU score 60–82
  const plotX = 0.62; const plotW = 4.95;
  const plotY = 1.08; const plotH = 3.7;
  const xMin = 0;  const xMax = 80;
  const yMin = 60; const yMax = 82;

  function toSlideX(params) { return plotX + (params - xMin) / (xMax - xMin) * plotW; }
  function toSlideY(score)  { return plotY + plotH - (score - yMin) / (yMax - yMin) * plotH; }

  // Chart background
  s.addShape(pres.shapes.RECTANGLE, {
    x: plotX, y: plotY, w: plotW, h: plotH,
    fill: { color: C.cardBg }, line: { color: "2D3748", pt: 1 }
  });

  // Grid lines (horizontal MMLU)
  [65, 70, 75, 80].forEach(score => {
    const gy = toSlideY(score);
    s.addShape(pres.shapes.LINE, {
      x: plotX, y: gy, w: plotW, h: 0,
      line: { color: "2D3D50", width: 0.75 }
    });
    s.addText(String(score), {
      x: plotX - 0.55, y: gy - 0.14, w: 0.5, h: 0.28,
      fontSize: 9, fontFace: "Calibri",
      color: C.muted, align: "right", valign: "middle", margin: 0
    });
  });

  // Vertical grid lines (params)
  [20, 40, 60, 80].forEach(p => {
    const gx = toSlideX(p);
    s.addShape(pres.shapes.LINE, {
      x: gx, y: plotY, w: 0, h: plotH,
      line: { color: "2D3D50", width: 0.75 }
    });
    s.addText(String(p) + "B", {
      x: gx - 0.25, y: plotY + plotH + 0.04, w: 0.5, h: 0.24,
      fontSize: 9, fontFace: "Calibri",
      color: C.muted, align: "center", valign: "top", margin: 0
    });
  });

  // Axis labels
  s.addText("MMLU Score", {
    x: 0.04, y: plotY + plotH / 2 - 0.6, w: 1.2, h: 1.2,
    fontSize: 9.5, fontFace: "Calibri", bold: true,
    color: C.muted, align: "center", rotate: 270, margin: 0
  });
  s.addText("Activated Parameters (B)", {
    x: plotX + plotW / 2 - 1.2, y: plotY + plotH + 0.3, w: 2.4, h: 0.28,
    fontSize: 9.5, fontFace: "Calibri", bold: true,
    color: C.muted, align: "center", margin: 0
  });

  // Data points
  const models = [
    { name: "LLaMA 3 8B",      params: 8,  mmlu: 65.0, col: C.muted   },
    { name: "Mixtral 8×7B",    params: 13, mmlu: 70.6, col: C.muted   },
    { name: "LLaMA 2 70B",     params: 70, mmlu: 69.0, col: C.muted   },
    { name: "DeepSeek 67B",    params: 67, mmlu: 73.0, col: C.muted   },
    { name: "Qwen1.5 72B",     params: 72, mmlu: 75.6, col: C.accent4 },
    { name: "Mixtral 8×22B",   params: 39, mmlu: 77.6, col: C.accent4 },
    { name: "LLaMA 3 70B",     params: 70, mmlu: 77.0, col: C.accent4 },
    { name: "DeepSeek-V2",     params: 21, mmlu: 78.5, col: C.accent  },
  ];

  const r = 0.115; // dot radius in inches
  models.forEach(m => {
    const cx = toSlideX(m.params);
    const cy = toSlideY(m.mmlu);
    const isV2 = m.name === "DeepSeek-V2";
    s.addShape(pres.shapes.OVAL, {
      x: cx - r, y: cy - r, w: r * 2, h: r * 2,
      fill: { color: m.col, transparency: isV2 ? 0 : 25 },
      line: { color: isV2 ? C.white : m.col, pt: isV2 ? 1.5 : 0.5 }
    });
    if (isV2) {
      s.addShape(pres.shapes.RECTANGLE, {
        x: cx + 0.18, y: cy - 0.32, w: 2.05, h: 0.62,
        fill: { color: "0D2035" }, line: { color: C.accent, pt: 1 }
      });
      s.addText("DeepSeek-V2 · 78.5 MMLU\n21B activated params", {
        x: cx + 0.2, y: cy - 0.32, w: 2.0, h: 0.62,
        fontSize: 9, bold: true, fontFace: "Calibri",
        color: C.accent, align: "left", valign: "middle", margin: 0
      });
    }
  });

  // ── Right: data table ──────────────────────────────────────────────────────
  const tableRows = [
    [
      { text: "Model",          options: { bold: true, color: C.white, fill: { color: "1E2D40" } } },
      { text: "Act. (B)",       options: { bold: true, color: C.white, fill: { color: "1E2D40" } } },
      { text: "MMLU",           options: { bold: true, color: C.white, fill: { color: "1E2D40" } } },
    ],
    [{ text: "DeepSeek-V2", options: { bold: true, fill: { color: "112030" } } },
     { text: "21",          options: { bold: true, fill: { color: "112030" } } },
     { text: "78.5",        options: { bold: true, color: C.accent, fill: { color: "112030" } } }],
    ["LLaMA 3 70B",    "70",  "77.0"],
    ["Mixtral 8×22B",  "39",  "77.6"],
    ["Qwen1.5 72B",    "72",  "75.6"],
    ["DeepSeek 67B",   "67",  "73.0"],
    ["Mixtral 8×7B",   "13",  "70.6"],
    ["LLaMA 2 70B",    "70",  "69.0"],
    ["LLaMA 3 8B",     "8",   "65.0"],
  ];

  s.addTable(tableRows, {
    x: 5.85, y: 1.05, w: 3.8, h: 4.15,
    colW: [2.0, 0.88, 0.92],
    border: { pt: 0.5, color: "2D3748" },
    fill: { color: C.cardBg },
    color: C.offWhite,
    fontSize: 10.5,
    fontFace: "Calibri",
    align: "center",
    rowH: 0.44,
  });
}

// ══════════════════════════════════════════════════════════════════════════════
// SLIDE 8 – Alignment Results
// ══════════════════════════════════════════════════════════════════════════════
{
  const s = pres.addSlide();
  s.background = { color: C.lightBg };
  addTopBar(s, C.accent3);
  addSlideTitle(s, "DeepSeek-V2 Chat (RL) Rivals Closed-Source Models on Chat Benchmarks", true);
  addFooter(s, true);

  // Pipeline bar — dark bg
  s.addShape(pres.shapes.RECTANGLE, {
    x: 0.35, y: 1.02, w: 9.3, h: 0.55,
    fill: { color: "1A2A42" }, line: { color: "3060A0", pt: 1 }
  });
  s.addText([
    { text: "Alignment Pipeline: ", options: { bold: true, color: C.offWhite } },
    { text: "Pretrain (8.1T tokens)  →  SFT (1.5M sessions)  →  GRPO Reinforcement Learning", options: { color: C.offWhite } }
  ], {
    x: 0.55, y: 1.02, w: 9.0, h: 0.55,
    fontSize: 12, fontFace: "Calibri",
    align: "left", valign: "middle", margin: 0
  });

  // 3 benchmark cards
  const benchmarks = [
    {
      name: "AlpacaEval 2.0",
      sub: "Length-Controlled Win Rate",
      val: "38.9%",
      desc: "Open-ended English instruction following. Competitive with leading closed-source models.",
      col: C.accent
    },
    {
      name: "MT-Bench",
      sub: "Score out of 10",
      val: "8.97",
      desc: "Multi-turn conversation quality across diverse task categories.",
      col: C.accent2
    },
    {
      name: "AlignBench",
      sub: "Overall Score (Chinese)",
      val: "7.91",
      desc: "#1 open-source model on Chinese alignment. Outperforms most closed-source Chinese models.",
      col: C.accent3
    },
  ];

  const cardH = 3.48;
  benchmarks.forEach((b, i) => {
    const bx = 0.35 + i * 3.13;
    s.addShape(pres.shapes.RECTANGLE, {
      x: bx, y: 1.72, w: 2.95, h: cardH,
      fill: { color: C.white }, line: { color: "D0D8E8", pt: 1 },
      shadow: makeShadow()
    });
    s.addShape(pres.shapes.RECTANGLE, {
      x: bx, y: 1.72, w: 2.95, h: 0.07,
      fill: { color: b.col }, line: { color: b.col }
    });
    s.addText(b.name, {
      x: bx + 0.12, y: 1.85, w: 2.71, h: 0.42,
      fontSize: 14, bold: true, fontFace: "Calibri",
      color: C.darkText, align: "center", valign: "top", margin: 0
    });
    s.addText(b.sub, {
      x: bx + 0.12, y: 2.3, w: 2.71, h: 0.3,
      fontSize: 10.5, fontFace: "Calibri",
      color: C.muted, align: "center", valign: "top", margin: 0
    });
    s.addText(b.val, {
      x: bx + 0.12, y: 2.65, w: 2.71, h: 0.95,
      fontSize: 40, bold: true, fontFace: "Calibri",
      color: b.col, align: "center", valign: "middle", margin: 0
    });
    s.addText(b.desc, {
      x: bx + 0.12, y: 3.68, w: 2.71, h: 1.4,
      fontSize: 11, fontFace: "Calibri",
      color: C.bodyText, align: "left", valign: "top", margin: 0
    });
  });
}

// ══════════════════════════════════════════════════════════════════════════════
// SLIDE 9 – Key Takeaways
// ══════════════════════════════════════════════════════════════════════════════
{
  const s = pres.addSlide();
  s.background = { color: C.darkBg };

  // Left accent bar
  s.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 0.35, h: 5.625,
    fill: { color: C.accent2 }, line: { color: C.accent2 }
  });

  s.addText("Key Takeaways", {
    x: 0.55, y: 0.1, w: 9, h: 0.58,
    fontSize: 28, bold: true, fontFace: "Calibri",
    color: C.white, align: "left", valign: "middle", margin: 0
  });
  s.addText("Architectural Innovation Unlocks Efficient Scaling", {
    x: 0.55, y: 0.68, w: 9, h: 0.3,
    fontSize: 12.5, italic: true, fontFace: "Calibri",
    color: C.offWhite, align: "left", valign: "middle", margin: 0
  });

  const takeaways = [
    { num: "01", title: "MLA: Strictly Better Than MHA",        body: "Low-rank KV joint compression cuts cache by 93.3% while exceeding standard MHA performance — a superior replacement for GQA/MQA.",    col: C.accent  },
    { num: "02", title: "DeepSeekMoE: Economical 236B Model",   body: "Shared + fine-grained routed experts enable training 236B parameters at 42.5% lower cost than a 67B dense model.",                     col: C.accent2 },
    { num: "03", title: "Pareto-Optimal on MMLU",               body: "21B activated params match or exceed 70B-class dense models (LLaMA 3 70B, Qwen1.5 72B) — more capability per FLOP.",                  col: C.accent3 },
    { num: "04", title: "5.76× Generation Throughput",          body: "Compressed KV cache enables near-6× higher throughput over DeepSeek 67B, making large-scale deployment economically practical.",       col: C.accent4 },
    { num: "05", title: "Strongest Open-Source Chinese Model",  body: "Chat (RL) tops AlignBench (7.91), MT-Bench (8.97), and AlpacaEval 2.0 (38.9% win rate), leading all open-source and most closed-source models in Chinese.", col: C.accent5 },
  ];

  // Layout: left col rows 0,2,4 (items 01,03,05); right col rows 0,1,2 (items 02,04) with taller cards
  // Equal-height approach: 3 cards left, 2 taller cards right — both fill same vertical space
  const leftX  = 0.5;
  const rightX = 5.22;
  const colW   = 4.48;
  const totalH = 4.3;  // content height from y=1.05 to y=5.35
  const startY = 1.05;

  // Left: 3 items with small gaps
  const leftCardH = (totalH - 2 * 0.12) / 3;
  [0, 1, 2].forEach(i => {
    const t = takeaways[i];
    const ty = startY + i * (leftCardH + 0.12);
    addCard(s, leftX, ty, colW, leftCardH, t.col);
    s.addText(t.num, {
      x: leftX + 0.18, y: ty + 0.1, w: 0.4, h: 0.35,
      fontSize: 13, bold: true, fontFace: "Calibri",
      color: t.col, align: "left", valign: "top", margin: 0
    });
    s.addText(t.title, {
      x: leftX + 0.6, y: ty + 0.1, w: colW - 0.7, h: 0.38,
      fontSize: 12, bold: true, fontFace: "Calibri",
      color: C.white, align: "left", valign: "top", margin: 0
    });
    s.addText(t.body, {
      x: leftX + 0.22, y: ty + 0.52, w: colW - 0.32, h: leftCardH - 0.58,
      fontSize: 10.5, fontFace: "Calibri",
      color: C.offWhite, align: "left", valign: "top", margin: 0
    });
  });

  // Right: 2 taller items
  const rightCardH = (totalH - 1 * 0.12) / 2;
  [3, 4].forEach(i => {
    const t = takeaways[i];
    const ty = startY + (i - 3) * (rightCardH + 0.12);
    addCard(s, rightX, ty, colW, rightCardH, t.col);
    s.addText(t.num, {
      x: rightX + 0.18, y: ty + 0.1, w: 0.4, h: 0.35,
      fontSize: 13, bold: true, fontFace: "Calibri",
      color: t.col, align: "left", valign: "top", margin: 0
    });
    s.addText(t.title, {
      x: rightX + 0.6, y: ty + 0.1, w: colW - 0.7, h: 0.38,
      fontSize: 12, bold: true, fontFace: "Calibri",
      color: C.white, align: "left", valign: "top", margin: 0
    });
    s.addText(t.body, {
      x: rightX + 0.22, y: ty + 0.52, w: colW - 0.32, h: rightCardH - 0.6,
      fontSize: 10.5, fontFace: "Calibri",
      color: C.offWhite, align: "left", valign: "top", margin: 0
    });
  });

  addFooter(s);
}

// ── Write ──────────────────────────────────────────────────────────────────
pres.writeFile({ fileName: "/app/output/final_deck.pptx" })
  .then(() => console.log("Done: /app/output/final_deck.pptx"))
  .catch(err => { console.error(err); process.exit(1); });

