// 3 comparison cards + result badge — fit within y=0.95 to y=5.25 (leave 0.15 above footer)
// Total available: 5.25 - 0.95 = 4.3". Reserve 0.45 for result badge + gap.
// Card area: 3.72". 3 cards + 2 gaps: each card = (3.72 - 2*0.1)/3 = 1.173
const rows = [
  { lbl: "Standard MHA",       desc: "Caches full K and V vectors for every attention head per token. At long contexts this becomes a severe memory bottleneck limiting batch size and throughput.", col: C.accent3 },
  { lbl: "GQA / MQA",          desc: "Reduce cache by sharing or merging heads across groups. Lowers memory, but sacrifices model quality compared to full MHA — a tradeoff MLA avoids.", col: C.accent4 },
  { lbl: "MLA (DeepSeek-V2)",   desc: "Low-rank joint KV compression: caches one compact latent vector c_KV per token. Full K/V reconstructed via learned projections. Decoupled RoPE. Outperforms MHA with 93.3% less cache.", col: C.accent2 },
];

const cardAreaH = 3.72;
const resultH   = 0.42;
const gapBeforeResult = 0.11;
const startYC   = 0.95;
const cardH     = (cardAreaH - 2 * 0.1) / 3;
rows.forEach((r, i) => {
  const ry = startYC + i * (cardH + 0.1);
  addCard(s, 5.35, ry, 4.3, cardH, r.col, C.white, r.col);
  s.addText(r.lbl, {
    x: 5.57, y: ry + 0.09, w: 3.95, h: 0.34,
    fontSize: 13, bold: true, fontFace: "Calibri",
    color: C.darkText, align: "left", valign: "top", margin: 0
  });
  s.addText(r.desc, {
    x: 5.57, y: ry + 0.46, w: 3.95, h: cardH - 0.55,
    fontSize: 11, fontFace: "Calibri",
    color: C.bodyText, align: "left", valign: "top", margin: 0
  });
});

// Result badge positioned below cards with gap, above footer
const resultY = startYC + cardAreaH + gapBeforeResult;
s.addShape(pres.shapes.RECTANGLE, {
  x: 5.35, y: resultY, w: 4.3, h: resultH,
  fill: { color: "1A3040" }, line: { color: C.accent2, pt: 1 }
});
s.addText("Result: MLA outperforms MHA with 93.3% less KV cache", {
  x: 5.4, y: resultY, w: 4.2, h: resultH,
  fontSize: 10.5, bold: true, fontFace: "Calibri",
  color: C.accent2, align: "center", valign: "middle", margin: 0
});

